  if(kind==='settlement-review'){openModal('<h2>Проверка заявки на оплату</h2>'+form(kind,'<label>Решение<select name="status"><option value="prepared">Подтвердить состав реестра</option><option value="cancelled">Отменить реестр и освободить активации</option></select></label>'+area('note','Результат проверки или причина отмены'),'Сохранить решение',id),'Заявка поставщика');return;}
  if(kind==='supplier-create'){const e=r&&current==='enquiries'?r:null;openModal(`<h2>Подключить поставщика</h2>${form(kind,input('name','Название компании',e?.company_name||'','text','required maxlength="180"')+input('email','Почта владельца кабинета',e?.email||'','email','required')+'<label class="checkline"><input name="invite" type="checkbox"><span>Отправить приглашение заполнить реквизиты и договор.</span></label><p class="note">Создаётся компания на подключении. Продажи откроются после проверки реквизитов, договора и программы.</p>','Создать компанию')}`,'Подключение компании');return;}
