  if(kind==='payment'){const orderId=id||'';openModal('<h2>Записать банковское поступление</h2>'+form(kind,input('reference','Уникальное банковское основание','','text','required maxlength="150"')+input('bankDate','Дата банка',new Date().toISOString().slice(0,10),'date','required')+input('amount','Фактически зачислено, ₽','','number','required min="0.01" step="0.01"')+input('orderId','Номер заказа — пусто, если ещё не определён',orderId,'number','min="1"')+area('comment','Комментарий','','')+check('bankVerified','Поступление проверено по банковской выписке.')+'<p class="note">Частичная оплата учитывается отдельно. Несопоставленное поступление не выпускает карту. Переплата требует отдельной сверки.</p>','Записать поступление'),'Банковское поступление');return;}
