  if(kind==='note'){const [objectKind,...rest]=id.split(':');openModal('<h2>Примечание оператора</h2>'+form(kind,`<input name="kind" type="hidden" value="${h(objectKind)}"><input name="objectId" type="hidden" value="${h(rest.join(':'))}">`+area('note','Комментарий'),'Записать'),'Примечание');return;}
