  if(kind==='company'){const co=detail.issuer.company;const {COMPANY_FIELDS}=await import('./merchant.js');openModal('<h2>Реквизиты поставщика</h2>'+form(kind,input('fulfillmentAddress','Фактический адрес выдачи товара или оказания услуги в Кыргызстане',co.fulfillmentAddress||'','text','required maxlength="500"')+COMPANY_FIELDS.map(([key,title,type])=>input(key,title,co[key]||'',type,'required maxlength="500"')).join('')+'<p class="note">Изменения реквизитов до появления заказов создают новую редакцию договора для подписания.</p>','Сохранить реквизиты',id),'Компания');return;}
