  if(kind==='settlement-create'){const selected=[...document.querySelectorAll('.admin-activation-select:checked')];if(!selected.length)throw Error('Выберите активации в реестре');const issuers=[...new Set(selected.map(e=>e.dataset.issuer))];if(issuers.length!==1)throw Error('Выберите активации одного поставщика');const chosen=selected.map(e=>rows.get(e.value));const gross=chosen.reduce((sum,r)=>sum+Number(r.nominal_minor),0);openModal('<h2>Сформировать выплату поставщику</h2><dl class="receipt"><dt>Поставщик</dt><dd>'+h(chosen[0].issuer_name)+'</dd><dt>Активаций</dt><dd>'+chosen.length+'</dd><dt>Полный номинал</dt><dd>'+fmt(gross)+'</dd><dt>Вознаграждение 0,1%</dt><dd>'+fmt(Math.round(gross*.001))+'</dd><dt>Банковские расходы 0,8%</dt><dd>'+fmt(Math.round(gross*.008))+'</dd><dt>Ориентир к перечислению</dt><dd>'+fmt(gross-Math.round(gross*.001)-Math.round(gross*.002)-Math.round(gross*.006))+'</dd></dl>'+form(kind,`<input name="issuerId" type="hidden" value="${h(issuers[0])}"><input name="activationIds" type="hidden" value="${h(JSON.stringify(selected.map(e=>e.value)))}">`+check('confirmed','Проверены ФИО, договоры, номиналы и отсутствие повторного включения. Банковский перевод выполняется отдельно.'),'Создать реестр'),'Реестр выплат');return;}
  if(kind==='bank-credit'){const s=detail.settlement;openModal('<h2>Подтвердить фактическое зачисление</h2><p>К получению: '+fmt(s.expected_net_minor)+'</p>'+form(kind,input('bankReference','Основание банка получателя','','text','required maxlength="150"')+input('amount','Зачислено, ₽',Number(s.expected_net_minor)/100,'number','required step="0.01" min="0.01"')+evidenceInput()+check('creditedVerified','Проверил фактическое зачисление по данным банка получателя.'),'Зафиксировать зачисление',id),'Зачисление поставщику');return;}
  if(kind==='settlement-event'){const s=detail.settlement;const names={sent:'Записать отправку перевода',returned:'Зафиксировать возврат перевода',reopen:'Подготовить повторную выплату',adjustment:'Корректировка суммы к перечислению'};openModal('<h2>'+names[id]+'</h2>'+form(kind,`<input name="kind" type="hidden" value="${h(id)}">`+input('reference','Документальное основание','','text','required maxlength="150"')+(id!=='reopen'?input('amount',id==='adjustment'?'Изменение суммы поставщику, ₽ — со знаком':'Фактическая сумма, ₽',id==='adjustment'?'':Number(s.expected_net_minor)/100,'number',`required step="0.01" ${id==='adjustment'?'':'min="0.01"'}`):'')+area('note','Комментарий к событию')+(id==='adjustment'?evidenceInput()+area('controlBasis','Основание дополнительного контроля и согласования')+check('controlConfirmed','Дополнительный контроль выполнен; при работе одним сотрудником документировано основание и проверка.'):evidenceInput())+check('evidenceVerified','Документальное основание и сумма проверены.'),'Записать событие',s.id),'Движение денег');return;}
  if(kind==='reconcile-balance'){openModal('<h2>Ручная сверка остатка платформы</h2>'+form(kind,input('providerReference','Основание сверки','','text','required maxlength="200"')+area('note','Что проверено и какой результат получен')+check('balanceVerified','Остаток платформы проверен отдельно от банковского поступления.'),'Сохранить результат сверки',id),'Сверка остатка');return;}
