  if(kind==='refund-paid'){openModal('<h2>Зафиксировать возврат покупателю</h2><p>К возврату: '+fmt(r.nominal_minor)+'</p>'+form(kind,input('amount','Фактически возвращено, ₽',Number(r.nominal_minor)/100,'number','required min="0.01" step="0.01"')+input('bankReference','Основание банковского возврата','','text','required maxlength="150"')+evidenceInput()+check('confirmed','Возврат выполнен и подтверждён банковским документом.'),'Зафиксировать выполненный возврат',id),'Возврат денег');return;}
