  if(kind==='refund-resolve'){openModal('<h2>Рассмотрение обращения</h2><p>'+h(r.reason)+'</p>'+form(kind,`<div class="field"><label>Решение<select name="status"><option value="review">На рассмотрении</option><option value="awaiting_issuer">Запрошен ответ поставщика</option><option value="approved">Возврат согласован</option>${r.redemption_status==='redeemed'?'<option value="paid">Возврат по основной покупке выполнен</option><option value="rejected">Мотивированный отказ по основной покупке</option>':''}</select></label></div>`+area('resolution','Решение, основание и ответ покупателю')+input('amount','Сумма выполненного возврата, ₽','','number','min="0.01" step="0.01"')+input('bankReference','Банковское основание — при выполненном возврате')+'<div class="field"><label>Подтверждение выполненного возврата<input name="evidenceFile" type="file" accept="application/pdf,image/png,image/jpeg"></label></div>'+check('groundsVerified','Проверены обстоятельства основной покупки и основания решения. Выпуск или погашение кода сами по себе не являются отказом.')+'<p class="note">Запрос к поставщику не переносит срок рассмотрения. Для неиспользованной карты банковский возврат оформляется отдельным действием после аннулирования.</p>','Сохранить и направить решение',id),'Обращение на возврат');return;}
